<script setup lang="ts">
import {Head,useForm} from '@inertiajs/vue3';
import AdminLayout from '@core/Layouts/AdminLayout.vue';
import PageHeader from '@core/Components/PageHeader.vue';
import {Button} from '@/components/ui/button'; import {Input} from '@/components/ui/input'; import {Label} from '@/components/ui/label';
const p=defineProps<{settings:any;availableRoles:string[]}>();
const f=useForm({currency:p.settings.currency,punishment_days_per_salary_day:Number(p.settings.punishment_days_per_salary_day||3),overtime_multiplier:Number(p.settings.overtime_multiplier||1),extra_duty_multiplier:Number(p.settings.extra_duty_multiplier||1),missing_punch_penalty_amount:Number(p.settings.missing_punch_penalty_amount),unpaid_leave_day_divisor:Number(p.settings.unpaid_leave_day_divisor),missing_attendance_policy:String(p.settings.missing_attendance_policy||'waive'),cutlist_review_required:Boolean(p.settings.cutlist_review_required),loan_approval_steps_text:(p.settings.loan_approval_steps||[]).map((s:any)=>typeof s==='string'?`${s}=${s==='Payroll'?'Administrator':s}`:`${s.label}=${s.role}`).join(', ')||'Payroll=Administrator'});
function save(){f.put(route('payroll.settings.update'))}
</script>
<template><AdminLayout :breadcrumbs="[{ title: 'Payroll' }, { title: 'Settings' }]"><Head title="Payroll settings"/><div class="max-w-5xl rounded-xl border bg-card p-6"><PageHeader title="Payroll policy settings" /><p class="mt-1 text-sm text-muted-foreground">Configure punishment eligibility, approved duty premiums, attendance penalties and staged loan approvals.</p><form @submit.prevent="save" class="mt-5 space-y-5"><div><Label>Currency code</Label><Input v-model="f.currency" maxlength="3"/></div><section class="rounded-lg border p-4"><h2 class="font-semibold">Late / early punishment</h2><p class="mb-3 text-xs text-muted-foreground">Applies only to employees whose HRM policy has “is punishable” enabled. One salary day is monthly gross salary ÷ 30, deducted for each configured number of affected workdays. New salary sheets default to without punishment.</p><Label>Affected days per one salary-day deduction</Label><Input v-model.number="f.punishment_days_per_salary_day" type="number" min="1" max="30"/></section><section class="rounded-lg border p-4"><h2 class="font-semibold">Approved overtime & extra-duty pay</h2><p class="mb-3 text-xs text-muted-foreground">Hourly basic = monthly basic salary ÷ (30 × employee duty hours). Only approved attendance-linked records are paid.</p><div class="grid grid-cols-2 gap-4"><div><Label>Overtime multiplier</Label><Input v-model.number="f.overtime_multiplier" type="number" min="0" max="20" step="0.01"/></div><div><Label>Extra-duty multiplier</Label><Input v-model.number="f.extra_duty_multiplier" type="number" min="0" max="20" step="0.01"/></div></div></section><div class="grid grid-cols-2 gap-4"><div><Label>Missing punch penalty per record</Label><Input v-model.number="f.missing_punch_penalty_amount" type="number" min="0" step="0.01"/></div><div><Label>Unpaid leave divisor (days)</Label><Input v-model.number="f.unpaid_leave_day_divisor" type="number" min="1" max="31" step="0.01"/></div></div><div class="col-span-2 rounded-lg border border-dashed p-3"><Label>Employee with no attendance record at all</Label><p class="mt-1 mb-2 text-xs text-muted-foreground">Applies to Active employees only &mdash; someone who has resigned or been terminated is settled by their final settlement, and an employee whose joining date has not arrived has nothing to deduct. A resign/terminate status therefore always means &ldquo;do not dock&rdquo;, whatever is chosen here.</p><select v-model="f.missing_attendance_policy" class="h-9 w-full rounded-md border bg-background px-2 text-sm"><option value="waive">Waive &mdash; pay the full month (a missing device export is not misconduct)</option><option value="apply">Apply the rule &mdash; deduct their rostered days like anyone else</option></select><p class="mt-2 text-xs text-muted-foreground">Employees <em>with</em> attendance are unaffected by this setting: if their punch policy is on, an absence is deducted; if HR switched their punishable flag off, their salary is paid in full.</p></div><section class="rounded-lg border p-4"><h2 class="font-semibold">Cutlist review</h2><p class="mb-2 text-xs text-muted-foreground">The cutlist is the salary sheet before it is final: generate it from HRM attendance data, review and adjust per employee (reasons logged), then approve. While this setting is on, queueing a month's salary sheet requires that month's <em>approved</em> cutlist.</p><label class="flex items-center gap-2 text-sm"><input type="checkbox" v-model="f.cutlist_review_required" class="size-4 rounded border" /><span>Require an approved cutlist before a salary sheet can be queued</span></label></section><div><Label>Loan approval tiers</Label><Input v-model="f.loan_approval_steps_text" placeholder="Manager=Manager, Finance=Finance"/><p class="mt-1 text-xs text-muted-foreground">Use Stage=Role pairs, for example Manager=Manager, Finance=Finance. Available roles: {{p.availableRoles.join(', ')}}. Every tier must use a different role and approvers must hold that tier’s role.</p></div><Button :disabled="f.processing">Save policy</Button></form></div></AdminLayout></template>